import React from 'react';
import { View } from 'react-native';
import { useFocusEffect } from 'expo-router';
import { Page, PageHeader } from '../../components/ui';
import { NotFound, ReportsList, useCanModerate } from '../../components/mod';

export default function ReportsTab() {
  const { ready, ok } = useCanModerate();
  const [k, setK] = React.useState(0);
  useFocusEffect(React.useCallback(() => setK((n) => n + 1), []));
  if (!ready) return <View style={{ flex: 1 }} />;
  if (!ok) return <NotFound />;
  return (
    <Page>
      <PageHeader icon="flag" eyebrow="Moderation" title="Reports" subtitle="Open reports from members" />
      <ReportsList key={k} />
    </Page>
  );
}
